import{_ as i,l as d,o as e,c as l,v as r,p as s,x as t,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"分布式 ID","description":"","frontmatter":{"title":"分布式 ID","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-id.md","filePath":"cs/distributed-id.md","lastUpdated":1789023840000}'),h={name:"cs/distributed-id.md"};function _(D,a,m,u,E,f){const o=d("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="分布式-id" tabindex="-1">分布式 ID <a class="header-anchor" href="#分布式-id" aria-label="Permalink to &quot;分布式 ID&quot;">​</a></h1><div class="epigraph"><p>唯一标识不必来自中心自增。雪花一类：时间 + 机器 + 序列。有序、可追溯、无单点；代价是时钟与机器编号的规格。</p><footer>—— 据 Twitter Snowflake 公开设计；UUID 标准；Lamport 时间戳对照整理</footer></div><p>上一课<a href="/cs/tail-at-scale">Tail at Scale</a>警告中心热点。缺口是<strong>生成主键</strong>：数据库 <code>AUTO_INCREMENT</code> 是单点尾延迟与故障点。本课钉 ID 方案与时钟依赖。后课地理复制会让「时间序」更假。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要求组合：全局唯一、大致时间可排序、高 QPS、故障隔离。UUID v4：唯一性好，无序，索引随机写碎。UUID v1：含时间与 MAC，隐私与时钟。Snowflake：毫秒时间戳、worker id、序列。worker id 来自配置或 ZK/etcd 租约——又把小 CP 请回来，但只在启动。</p><p>缺口：时钟回拨使时间戳段重用，破唯一。要等或用<a href="/cs/hlc">HLC</a>或拒绝。多机房 worker id 空间要划片，否则碰撞。</p><p><span class="marginnote">Snowflake 是工程博客级源头，不是 TODS。数据库号段（一次取一千）是折中：中心少热点，ID 仍大致单调。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选：无序唯一用随机；要局部单调用雪花或号段。号段：每个应用实例从 RSM 拿一段，本地发完再拿——段边界可有洞（实例崩）。洞通常可接受，连续当规格则必须中心。</p>',9)),(e(),s(c,null,{default:t(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLK%5B%22%E6%97%B6%E9%97%B4%22%5D%20--%3E%20SF%5B%22%E9%9B%AA%E8%8A%B1%20ID%22%5D%0A%20%20WID%5B%22worker%20%E7%BC%96%E5%8F%B7%22%5D%20--%3E%20SF%0A%20%20SEQ%5B%22%E5%BA%8F%E5%88%97%22%5D%20--%3E%20SF%0A%20%20RSM%5B%22%E5%8F%B7%E6%AE%B5%22%5D%20--%3E%20LOCAL%5B%22%E6%9C%AC%E5%9C%B0%E5%8F%91%E6%94%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要用墙钟毫秒当唯一：同毫秒多机碰撞。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与线性一致计数器：中心 <code>INCR</code> 唯一且单调，QPS 受单日志限制，尾差。雪花把唯一性拆到时间维，单调只在同一 worker 且时钟不回拨。跨 worker 比较大小 ≈ 比较时间，受 \\(\\varepsilon\\) 限制——不能当因果。</p><p>本课不写区块链 nonce 挖矿。也不写证件号合规。</p><p>热行：以 ID 为分区键且 ID 时间单调，则写总打最新分区（Mongo 等经典坑）。要哈希，或在高位加 shard 随机。这是热键在主键上的投影。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定 64 位布局。后课默认：规模 ID 不用单点自增；雪花要声明回拨策略与 worker 分配。地理复制下一课让「谁的毫秒」更乱，跨区 ID 更要划 worker 空间。滚动升级时 worker 重编号不得碰撞。</p><p>唯一是安全；有序是性能与产品。两件事分开买。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中心自增唯一但成尾与单点。</li><li>雪花：时间+机器+序列；回拨与 worker 分配是规格。</li><li>单调 ID 当分区键会写热分区。</li><li>出处：Snowflake 设计；UUID；对照 Lamport 钟。</li></ul>',10))])}const S=i(h,[["render",_]]);export{I as __pageData,S as default};
